WITH lines AS (SELECT id, service, log_ts, latency_ms, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, v) SELECT id, service, log_ts, latency_ms, v, DENSE_RANK() OVER (PARTITION BY MONTH(log_ts), k ORDER BY latency_ms DESC NULLS LAST) latency_ms_dense_rank, CUME_DIST() OVER (PARTITION BY k ORDER BY latency_ms NULLS LAST) latency_ms_cume_dist, SUM(latency_ms) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) latency_ms_sum_2h, RANK() OVER (ORDER BY latency_ms) latency_ms_rank, MIN(latency_ms) OVER (PARTITION BY MONTH(log_ts), service) log_ts_month_min_latency_ms FROM lines;
